import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Refactoring Playbook","description":"Engineering playbook for refactoring workflow","frontmatter":{"title":"Refactoring Playbook","description":"Engineering playbook for refactoring workflow"},"headers":[],"relativePath":"playbooks/refactoring.md","filePath":"playbooks/refactoring.md","lastUpdated":1784485118000}'),i={name:"playbooks/refactoring.md"};function n(s,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="refactoring-playbook" tabindex="-1">Refactoring Playbook <a class="header-anchor" href="#refactoring-playbook" aria-label="Permalink to &quot;Refactoring Playbook&quot;">​</a></h1><h1 id="playbook-refactoring" tabindex="-1">Playbook: Refactoring <a class="header-anchor" href="#playbook-refactoring" aria-label="Permalink to &quot;Playbook: Refactoring&quot;">​</a></h1><p><strong>Goal:</strong> Improve code structure, readability, and maintainability without changing behavior.</p><p><strong>Trigger:</strong> Code is working but needs improvement — duplication, complexity, poor naming, wrong pattern.</p><p><strong>Inputs:</strong></p><ul><li>Files or modules to refactor</li><li>Refactoring goal (readability, performance, pattern change, extraction)</li><li>Constraints (must not break API, must maintain compatibility)</li></ul><p><strong>Outputs:</strong></p><ul><li>Refactored code with same behavior</li><li>Updated tests (if applicable)</li><li>Documentation of changes</li><li>Pattern established for future code</li></ul><p>----|------| | <code>architect</code> | Strategy — what to refactor and how | | <code>build</code> | Implementation — execute the refactoring | | <code>reviewer</code> | Verify behavior is preserved | | <code>frontend</code> | UI component refactoring | | <code>backend</code> | Server logic refactoring | | <code>database</code> | Schema or query refactoring |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>refactoring-patterns</code></td><td>Always — refactoring strategies and patterns</td></tr><tr><td><code>clean-architecture</code></td><td>Structural refactoring</td></tr><tr><td><code>react-patterns</code></td><td>React component refactoring</td></tr><tr><td><code>nextjs-app-router</code></td><td>Next.js-specific refactoring</td></tr><tr><td><code>typescript-patterns</code></td><td>Type system improvements</td></tr><tr><td><code>state-management</code></td><td>State architecture refactoring</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/review</code></td><td>Before and after refactoring</td></tr><tr><td><code>/performance-check</code></td><td>Ensure refactoring doesn&#39;t hurt performance</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-assess-10-min" tabindex="-1">Step 1: Assess (10 min) <a class="header-anchor" href="#step-1-assess-10-min" aria-label="Permalink to &quot;Step 1: Assess (10 min)&quot;">​</a></h3><ol><li><strong>Read the code</strong> — Understand what it does currently</li><li><strong>Identify problems</strong> — Duplication, complexity, wrong pattern</li><li><strong>Map dependencies</strong> — What depends on this code?</li><li><strong>Check tests</strong> — Are there existing tests?</li><li><strong>Plan approach</strong> — Which refactoring pattern applies?</li></ol><p>Common refactoring patterns:</p><ul><li><strong>Extract Function</strong> — Break long function into smaller ones</li><li><strong>Extract Component</strong> — Break large component into smaller ones</li><li><strong>Rename</strong> — Improve naming for clarity</li><li><strong>Move</strong> — Relocate code to correct module</li><li><strong>Inline</strong> — Remove unnecessary abstraction</li><li><strong>Replace with Pattern</strong> — Apply established design pattern</li><li><strong>Simplify Conditionals</strong> — Reduce nesting, use early returns</li><li><strong>Type Narrowing</strong> — Add explicit types, remove <code>any</code></li></ul><h3 id="step-2-plan-5-min" tabindex="-1">Step 2: Plan (5 min) <a class="header-anchor" href="#step-2-plan-5-min" aria-label="Permalink to &quot;Step 2: Plan (5 min)&quot;">​</a></h3><ol><li><strong>Define the target state</strong> — What should the code look like?</li><li><strong>Order operations</strong> — What to change first?</li><li><strong>Identify risks</strong> — What could break?</li><li><strong>Set checkpoints</strong> — Verify at each step</li></ol><h3 id="step-3-execute-varies" tabindex="-1">Step 3: Execute (varies) <a class="header-anchor" href="#step-3-execute-varies" aria-label="Permalink to &quot;Step 3: Execute (varies)&quot;">​</a></h3><ol><li><strong>Make one change at a time</strong></li><li><strong>Verify after each change</strong> — Build passes, behavior same</li><li><strong>Commit frequently</strong> — Small, reversible commits</li><li><strong>Follow existing patterns</strong> — Don&#39;t introduce new conventions mid-refactor</li></ol><h3 id="step-4-verify-10-min" tabindex="-1">Step 4: Verify (10 min) <a class="header-anchor" href="#step-4-verify-10-min" aria-label="Permalink to &quot;Step 4: Verify (10 min)&quot;">​</a></h3><ol><li><strong>Run <code>/review</code></strong> — Verify quality improvement</li><li><strong>Run build</strong> — <code>npm run build</code> passes</li><li><strong>Test behavior</strong> — Same input, same output</li><li><strong>Check performance</strong> — No regression</li><li><strong>Verify types</strong> — No new <code>any</code> types</li></ol><h3 id="step-5-document-5-min" tabindex="-1">Step 5: Document (5 min) <a class="header-anchor" href="#step-5-document-5-min" aria-label="Permalink to &quot;Step 5: Document (5 min)&quot;">​</a></h3><ol><li><strong>Update comments</strong> — If logic is non-obvious</li><li><strong>Update project AGENTS.md</strong> — If new pattern established</li><li><strong>Commit with clear message</strong> — <code>refactor(scope): description</code></li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] Code behavior is identical before and after</li><li>[ ] Build passes</li><li>[ ] No performance regression</li><li>[ ] Code is simpler or clearer than before</li><li>[ ] No new <code>any</code> types introduced</li><li>[ ] Existing tests still pass (if applicable)</li><li>[ ] Related code is checked for similar improvements</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>Code is cleaner, simpler, or more maintainable</li><li>Behavior is preserved</li><li>No regressions introduced</li><li>Pattern is documented for future use</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Refactoring + feature in one commit</td><td>Hard to review and revert</td><td>Separate refactoring from feature</td></tr><tr><td>Changing behavior during refactor</td><td>Introduces bugs</td><td>Only change structure, not behavior</td></tr><tr><td>Over-refactoring</td><td>Adds unnecessary abstraction</td><td>Refactor to &quot;good enough&quot;</td></tr><tr><td>Not testing after each step</td><td>Accumulated errors</td><td>Verify continuously</td></tr><tr><td>Ignoring dependent code</td><td>Breaks callers</td><td>Check all dependents</td></tr><tr><td>Refactoring without understanding</td><td>Makes code worse</td><td>Understand before changing</td></tr><tr><td>Big-bang refactoring</td><td>High risk, hard to review</td><td>Small, incremental changes</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>',38)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
